/* ── FLUX PLANNER · app.js v2 ── */

// ══ STORAGE — must be first, everything below depends on it ══
//
// IMPORTANT: load / save automatically apply the FluxImpersonate prefix
// (defined later in this file). When the owner is "previewing as" a teacher,
// every read & write transparently goes to a per-teacher localStorage bubble
// (e.g.  imp:abenitez@bloomfield.org:flux_tasks ) instead of the owner's real
// keys. The owner's real planner data never moves and never mixes with the
// preview bubble. See FLUX_IMPERSONATION_GLOBAL_KEYS below for the small
// denylist of keys that must stay shared across personas (migration markers,
// owner-only audit, theme prefs, OAuth tokens, etc.).
const FLUX_IMPERSONATION_GLOBAL_KEYS=new Set([
  // Impersonation control state itself — must be unprefixed or we'd recurse.
  'flux_owner_impersonate',
  // Migration / version markers
  'flux_data_version','flux_splash_shown',
  // Owner-only operations data — only ever touched while signed in as owner
  'flux_dev_accounts','flux_platform_config','flux_platform_broadcast',
  'flux_owner_audit','flux_feedback_inbox','flux_feedback_tombstones',
  'flux_dev_mode',
  // Chrome extension bridge (device-local; not per-impersonation bubble)
  'flux_chrome_extension_id',
  // Pre-auth / one-shot signup state
  'flux_pref_role','flux_pending_staff_role','flux_pending_staff_name',
  'flux_pending_staff_subject',
  // Last signed-in user (device-local; used for account-switch wipe + pre-init scrub)
  'flux_last_user_id','flux_last_user_email',
  // UI / theme prefs — kept shared so the dev experience doesn't reset
  // every time you switch into a different teacher to test something.
  'flux_user_name','flux_accent','flux_accent_rgb','flux_theme',
  'flux_profile_pic',
  'flux_perf_snappy','flux_ui_density','flux_mood_tint_enabled',
  'flux_nav_counts_v1','flux_layout_dashboard_v1','flux_layout_calendar_v1',
  'flux_last_sync',
]);
const FLUX_IMPERSONATION_GLOBAL_PREFIXES=[
  // External integrations — owner's own OAuth/connection state, not the
  // impersonated teacher's. (When teachers sign in for real they get their
  // own tokens.)
  'flux_canvas_','flux_extension_',
  'flux_ai_connections_','flux_ai_model_route_',
  // BYOK multi-provider AI keys + default route — owner-device-local secrets,
  // never the impersonated teacher's. Must stay un-prefixed so previewing as a
  // teacher doesn't hide the owner's keys or write them into a persona bubble.
  'flux_aiprov_',
  // Per-device / per-auth-user prefs (suffix may include user id)
  'flux_staff_mode_','flux_feature_flags_cache_v1',
  'flux_role_setup_v1_',
  // Supabase auth tokens are stored under sb-... in localStorage by the SDK.
  'sb-',
];
function fluxImpersonationPrefix(){
  try{
    const raw=localStorage.getItem('flux_owner_impersonate');
    if(!raw)return '';
    const v=JSON.parse(raw);
    if(!v||typeof v!=='object'||!v.email)return '';
    return 'imp:'+String(v.email).toLowerCase().trim()+':';
  }catch(_){return '';}
}
function fluxNamespacedKey(k){
  if(!k||typeof k!=='string')return k;
  if(FLUX_IMPERSONATION_GLOBAL_KEYS.has(k))return k;
  for(let i=0;i<FLUX_IMPERSONATION_GLOBAL_PREFIXES.length;i++){
    if(k.indexOf(FLUX_IMPERSONATION_GLOBAL_PREFIXES[i])===0)return k;
  }
  if(k.indexOf('imp:')===0)return k; // already namespaced — don't double-prefix
  const pre=fluxImpersonationPrefix();
  return pre?pre+k:k;
}
function _fluxLoadRaw(k,def){try{const v=localStorage.getItem(fluxNamespacedKey(k));return v?JSON.parse(v):def;}catch(e){return def;}}
function _fluxSaveRaw(k,v){try{localStorage.setItem(fluxNamespacedKey(k),JSON.stringify(v));}catch(e){console.warn('Storage full',e);}}
const load=(k,def)=>{
  const o=_fluxLoadRaw(k,def);
  try{if(window.FluxDebug&&typeof FluxDebug.traceStorage==='function')FluxDebug.traceStorage('load',k);}catch(e){}
  return o;
};
const save=(k,v)=>{
  try{if(window.FluxDebug&&typeof FluxDebug.traceStorage==='function')FluxDebug.traceStorage('save',k);}catch(e){}
  _fluxSaveRaw(k,v);
};
/** Prefs historically stored as raw '1'/'0' or via save() (JSON); respects namespacing. */
function fluxLoadLegacy01(k){
  try{
    const v=load(k,null);
    if(v!==null&&v!==undefined){
      if(v===1||v===true||v==='1')return true;
      if(v===0||v===false||v==='0')return false;
    }
  }catch(_){}
  try{return localStorage.getItem(fluxNamespacedKey(k))==='1';}catch(_){ return false; }
}
function fluxSaveLegacy01(k,on){save(k,on?'1':'0');}
function fluxHasLegacy01Pref(k){
  try{
    const v=load(k,null);
    if(v!==null&&v!==undefined)return true;
  }catch(_){}
  try{return localStorage.getItem(fluxNamespacedKey(k))!==null;}catch(_){return false;}
}
/** Desktop planner-wide: threads sidebar collapsed until user opens it. */
function fluxAISidebarHidden(){
  if(fluxHasLegacy01Pref('flux_ai_sidebar_hidden'))return fluxLoadLegacy01('flux_ai_sidebar_hidden');
  try{return window.matchMedia('(min-width:769px)').matches;}catch(_){return false;}
}
/** Plain string prefs (raw localStorage or JSON string via save()). */
function fluxLoadStoredString(k,def){
  try{
    const v=load(k,null);
    if(v!==null&&v!==undefined&&String(v).length)return String(v);
  }catch(_){}
  try{
    const nk=fluxNamespacedKey(k);
    const raw=localStorage.getItem(nk);
    if(raw==null||raw==='')return def;
    try{return String(JSON.parse(raw));}catch(_){return String(raw);}
  }catch(_){ return def; }
}
function fluxSaveStoredString(k,v){save(k,String(v));}
window.fluxLoadLegacy01=fluxLoadLegacy01;
window.fluxSaveLegacy01=fluxSaveLegacy01;
window.fluxLoadStoredString=fluxLoadStoredString;
window.fluxSaveStoredString=fluxSaveStoredString;
window.fluxNamespacedKey=fluxNamespacedKey;
window.fluxImpersonationPrefix=fluxImpersonationPrefix;
/** ESM helpers (`public/js/core/storage.js`) use this so reads/writes match `fluxNamespacedKey` + impersonation. */
window.FluxStorage={load,save};
// Classic-script scope bridge: ~129 reads of `window.save` and ~105 of
// `window.load` across modules silently no-op without these (top-level
// `const` is not a window property). Same root cause as the cowork bug.
window.save=save;
window.load=load;

// ── Phase 2 · DEV-only diagnostics (no-op unless explicitly enabled) ──
// Master: window.FLUX_DEBUG = true  OR  localStorage.setItem('FLUX_DEBUG','1')
// Scoped (localStorage, value '1'): FLUX_DEBUG_NAV, FLUX_DEBUG_ROLE, FLUX_DEBUG_IMP,
//   FLUX_DEBUG_BUS, FLUX_DEBUG_STORAGE, FLUX_DEBUG_AI
(function initFluxDebug(){
  if(window.FluxDebug&&window.FluxDebug.__fromCoreModule)return;
  // Debug toggles are intentionally unprefixed (device-global; not per-impersonation bubble).
  function lsGet(k){try{return localStorage.getItem(k);}catch(e){return null;}}
  function onFlag(sub){
    try{
      if(typeof window!=='undefined'&&window.FLUX_DEBUG===true)return true;
      if(lsGet('flux_debug')==='on')return true;
      if(lsGet('FLUX_DEBUG')==='1')return true;
      if(sub&&lsGet('FLUX_DEBUG_'+String(sub).toUpperCase())==='1')return true;
    }catch(e){}
    return false;
  }
  const _throttle=Object.create(null);
  function throttle(key,ms){
    const t=Date.now();
    const last=_throttle[key]||0;
    if(t-last<ms)return false;
    _throttle[key]=t;
    return true;
  }
  window.FluxDebug={
    on:onFlag,
    traceStorage(op,key){
      if(!onFlag('STORAGE'))return;
      if(!throttle('s:'+op+':'+String(key),900))return;
      let pre='',nk='';
      try{pre=typeof fluxImpersonationPrefix==='function'?fluxImpersonationPrefix():'';}catch(e){}
      try{nk=typeof fluxNamespacedKey==='function'?fluxNamespacedKey(key):String(key);}catch(e){nk=String(key);}
      console.log('[FluxStorage]',{op,key,impPrefix:pre||'(none)',namespacedKey:nk});
    },
    navStart(payload){
      if(!onFlag('NAV'))return;
      console.log('[FluxNav:start]',payload);
    },
    navEnd(payload){
      if(!onFlag('NAV'))return;
      console.log('[FluxNav:end]',payload);
    },
    traceBusEmit(e,d){
      if(!onFlag('BUS'))return;
      if(!throttle('bus:'+e,1400))return;
      const n=(FluxBus&&FluxBus._h&&FluxBus._h[e])?FluxBus._h[e].length:0;
      const hint=d&&typeof d==='object'&&'id'in d?{id:d.id}:undefined;
      console.log('[FluxBus:emit]',{e,listeners:n,...hint});
    },
    ai(ev,payload){
      if(!onFlag('AI'))return;
      if(!throttle('ai:'+ev,400))return;
      console.log('[FluxAI:'+ev+']',payload);
    },
  };
})();

// Defense in depth: impersonation is owner-only. If the most recent user on
// this browser wasn't the owner, scrub any stale `flux_owner_impersonate`
// key BEFORE the module-init `let tasks = load(...)` calls below run — so
// they don't briefly populate from the wrong namespace. The post-sign-in
// handler clears it too, but that runs later.
try{
  const lastEmail=String(fluxLoadStoredString('flux_last_user_email','')).trim().toLowerCase();
  if(lastEmail&&lastEmail!=='azfermohammed21@gmail.com'){
    localStorage.removeItem(fluxNamespacedKey('flux_owner_impersonate'));
  }
}catch(_){}

// ══ DATA VERSION — bump when schema needs pruning; never drop user task/note data ══
const DATA_VERSION=6;
(function checkDataVersion(){
  const stored=Number(load('flux_data_version',0))||0;
  if(stored>=DATA_VERSION)return;
  const keepExact=new Set([
    'flux_data_version','flux_splash_shown',
    'flux_perf_snappy','flux_ui_density','flux_mood_tint_enabled',
    'flux_nav_counts_v1','flux_layout_dashboard_v1','flux_layout_calendar_v1',
    'flux_canvas_token','flux_canvas_url','flux_canvas_host',
    'flux_canvas_last_view','flux_canvas_last_params',
    'flux_canvas_autosync','flux_canvas_last_sync',
    'flux_canvas_due_filter','flux_canvas_hub_tab',
    'flux_canvas_split','flux_canvas_sidebar_collapsed',
    'flux_canvas_embed_url','flux_canvas_hub_cache','flux_canvas_ai_focus',
    'flux_ai_connections_items_v1','flux_ai_connections_custom_v1','flux_ai_model_route_v1',
    'flux_chrome_extension_id','flux_profile_pic',
    'tasks',
  ]);
  function shouldKeepKey(k){
    if(!k)return false;
    if(keepExact.has(k))return true;
    if(k.startsWith('flux_'))return true;
    // Supabase JS client session + preview bubbles must survive version bumps.
    if(k.startsWith('sb-')||k.includes('supabase'))return true;
    if(k.startsWith('imp:'))return true;
    return false;
  }
  Object.keys(localStorage).forEach(k=>{
    if(shouldKeepKey(k))return;
    try{
      console.warn('[Flux] migration: dropping non-preserved localStorage key:',k);
    }catch(e){}
    try{localStorage.removeItem(k);}catch(e){}
  });
  save('flux_data_version',DATA_VERSION);
  console.log('[Flux] Data migration applied → version',DATA_VERSION);
})();

(function(){
  function estBytes(){
    let n=0;
    try{
      for(let i=0;i<localStorage.length;i++){
        const k=localStorage.key(i);
        if(k)n+=(k.length+(localStorage.getItem(k)||'').length)*2;
      }
    }catch(e){}
    return n;
  }
  window.fluxEstimateLocalStorageBytes=estBytes;
  window.fluxCompactStorageIfNeeded=function(){
    if(estBytes()<=5*1024*1024)return;
    try{
      const notes=load('flux_notes',[]);
      if(Array.isArray(notes)&&notes.length>240)save('flux_notes',notes.slice(-240));
    }catch(e){}
    // AI chat shards use physical keys (may include `imp:…` prefix). Must read/write `k` as-is — not `load(key)` (would re-namespace).
    try{
      for(let i=localStorage.length-1;i>=0;i--){
        const k=localStorage.key(i);
        if(!k||!k.includes('flux_ai_chats'))continue;
        const arr=JSON.parse(localStorage.getItem(k)||'null');
        if(!Array.isArray(arr))continue;
        let dirty=false;
        for(let j=0;j<arr.length;j++){
          const ch=arr[j];
          if(ch&&Array.isArray(ch.messages)&&ch.messages.length>100){ch.messages=ch.messages.slice(-100);dirty=true;}
        }
        if(dirty)localStorage.setItem(k,JSON.stringify(arr));
      }
    }catch(e){}
  };
  window.fluxCompactStorageIfNeeded();
})();

