window.closeEcScheduleModal=closeEcScheduleModal;
window.setEcScheduleType=setEcScheduleType;
window.saveEcCalendarSchedule=saveEcCalendarSchedule;
window.onWeeklyExtraLinkChange=onWeeklyExtraLinkChange;
window.onAddEventExtraPick=onAddEventExtraPick;


// ══ STATE ══
let tasks=load('tasks',[]);
// Expose `tasks` on window as a LIVE view of this block-scoped binding.
// app.js is a classic script, so top-level `let` is NOT a window property —
// yet ~35 feature modules (Co-work, SRS, bulk-filter, progress-streak,
// mobile-swipe, elevate, deep-links, …) read `window.tasks`, and helpers like
// flux-storage-repair / flux-offline-sync only act when it's already defined.
// A getter/setter closes over the real binding so reads always reflect the
// current array (even after `tasks=tasks.filter(...)` reassignments) and any
// `window.tasks = x` write updates the real binding instead of shadowing it.
try{
  Object.defineProperty(window,'tasks',{
    configurable:true,
    enumerable:true,
    get:function(){return tasks;},
    set:function(v){if(Array.isArray(v))tasks=v;},
  });
}catch(_){ window.tasks=tasks; }
let notes=load('flux_notes',[]);
let habits=load('flux_habits',[]);
function getFluxHabits(){return habits;}
function setFluxHabits(next){habits=Array.isArray(next)?next:[];save('flux_habits',habits);syncKey('habits',habits);}
try{window.getFluxHabits=getFluxHabits;window.setFluxHabits=setFluxHabits;}catch(_){}
let goals=load('flux_goals',[]);
let colleges=load('flux_colleges',[]);
let moodHistory=load('flux_mood',[]);
let confidences=load('flux_conf',{});
let studyDNA=load('flux_dna',[]);
let subjectBudgets=load('flux_budgets',{});
let sessionLog=load('flux_session_log',[]);
let settings=load('flux_settings',{panic:true,quiet:true,dndStart:'07:50',dndEnd:'14:30',dailyGoalHrs:2,notifyBrowser:false,notifyDueSoon:true,classScheduleDisplay:'full'});
let schoolInfo=load('flux_school',{locker:'',combo:'',counselor:'',studentID:''});
let classes=load('flux_classes',[]);
// Backfill structured course metadata on legacy entries. Names are never
// rewritten — pre-fix stripped names are unrecoverable, and nothing is
// stripped going forward (see parseClassLevel/cleanClassName).
(function(){
  let changed=false;
  (Array.isArray(classes)?classes:[]).forEach(c=>{
    if(c&&c.name&&typeof c.level!=='string'){c.level=parseClassLevel(c.name).level;changed=true;}
  });
  if(changed)try{save('flux_classes',classes);}catch(_){}
})();
let teacherNotes=load('flux_teacher_notes',[]);

/** Done tasks missing completedAt get a best-effort timestamp (streaks, week strip, AI actions). Safe to run often. */
function migrateCompletedAtBackfill(){
  let changed=false;
  const infer=t=>{
    if(t.updatedAt)return t.updatedAt;
    if(t.createdAt)return t.createdAt;
    if(t.date){
      const d=fluxParseLocalYMD(t.date);
      if(d){d.setHours(17,0,0,0);return d.getTime();}
    }
    if(typeof t.id==='number'&&t.id>1e12)return t.id;
    return Date.now();
  };
  tasks.forEach(t=>{
    if(!t.done||t.completedAt)return;
    t.completedAt=infer(t);
    changed=true;
  });
  if(changed){save('tasks',tasks);syncKey('tasks',tasks);}
}

