async function commitEducatorRoleFromUpgrade(det){
  const u=(typeof currentUser!=='undefined'&&currentUser)||window.currentUser;
  const sb=typeof getSB==='function'?getSB():null;
  if(!u||!sb||!det||!det.role)return;
  const displayName=det.name||det.display_name||u.user_metadata?.full_name||u.email?.split('@')[0]||null;
  const {error}=await sb.from('user_roles').upsert({
    user_id:u.id,
    role:det.role,
    display_name:displayName,
    subject:det.subject||null,
    school:(window.FluxSchool?.IAE?.name||'International Academy East'),
    updated_at:new Date().toISOString(),
  });
  if(error){
    if(typeof showToast==='function')showToast('Could not update account: '+error.message,'error');
    return;
  }
  if(det.role==='counselor'){
    try{await ensureCounselorRecord(sb,'counselor');}catch(_){}
  }
  try{await FluxRole.load();}catch(_){}
  window._userRole=FluxRole.current;
  try{await fluxRouteAfterAuth('verification');}catch(_){}
  try{syncStudentEducatorUpgradeCard();}catch(_){}
  if(typeof showToast==='function')showToast('School workspace on. Use Work / Personal at the top anytime.','success');
}

async function startUpgradeToSchoolWorkspace(){
  try{
    const u=(typeof currentUser!=='undefined'&&currentUser)||window.currentUser;
    if(!u){if(typeof showToast==='function')showToast('Sign in first.','info');return;}
    try{await FluxRole.load();}catch(_){}
    if(FluxRole.current!=='student'){
      if(typeof showToast==='function')showToast('You already have educator access. Use Work / Personal at the top.','info');
      return;
    }
    const email=String(u.email||'').toLowerCase().trim();
    const dirRec=window.FluxStaffDirectory?.findByEmail?.(email)||null;
    let det=null;
    if(dirRec){
      if(typeof showToast==='function')showToast('Confirm your staff directory entry…','info');
      det=await showStaffDetailsForm();
    }else{
      det=await showPersonalEducatorSelfSignupModal();
    }
    if(!det||!det.role)return;
    await commitEducatorRoleFromUpgrade(det);
  }catch(e){
    console.warn('[Flux] startUpgradeToSchoolWorkspace',e);
    if(typeof showToast==='function')showToast('Something went wrong. Try again.','error');
  }
}
window.startUpgradeToSchoolWorkspace=startUpgradeToSchoolWorkspace;

const strip=html=>esc(String(html??'').replace(/<[^>]*>?/g,'')).slice(0,120);
// Canonical "today" for every surface (23 modules delegate to window.todayStr).
// Must be LOCAL and live: toISOString() rolls over at UTC midnight, which put
// this a day ahead of the calendar and FluxNow (both fluxLocalYMD) every evening
// in the Americas, so closures/rest days keyed here missed their lookups.
const todayStr=()=>fluxLocalYMD(new Date());
const fmtTime=t=>{if(!t)return'';const[h,m]=t.split(':').map(Number);const ampm=h>=12?'PM':'AM';return`${h%12||12}:${String(m).padStart(2,'0')} ${ampm}`;};
window.strip=strip; window.todayStr=todayStr; window.fmtTime=fmtTime;

function refreshAIContext(){
  const now=new Date();now.setHours(0,0,0,0);
  const ago7=new Date(now);ago7.setDate(now.getDate()-7);
  const fwd14=new Date(now);fwd14.setDate(now.getDate()+14);
  return{recent:tasks.filter(t=>t.done&&t.date&&new Date(t.date+'T00:00:00')>=ago7),upcoming:tasks.filter(t=>!t.done&&t.date&&new Date(t.date+'T00:00:00')>=now&&new Date(t.date+'T00:00:00')<=fwd14)};
}
function quietHours(){if(!settings.quiet)return false;const now=new Date(),h=now.getHours(),m=now.getMinutes(),cur=h*60+m;const[sh,sm]=(settings.dndStart||'07:50').split(':').map(Number);const[eh,em]=(settings.dndEnd||'14:30').split(':').map(Number);return cur>=sh*60+sm&&cur<=eh*60+em;}
function panicCheck(task){if(!settings.panic||quietHours())return;const now=new Date(),due=new Date((task.date||'')+'T23:59:00');if((due-now)/3600000<12&&(due-now)>0)checkAllPanic();}
function checkAllPanic(){if(!settings.panic||quietHours()){hidePanic();return;}const now=new Date(),in12=new Date(now.getTime()+12*3600000),ts=todayStr();const urgent=tasks.filter(t=>{if(!t.done&&t.date){if(t.date===ts&&typeof isBreak==='function'&&isBreak(ts))return false;const d=new Date(t.date+'T23:59:00');return d>now&&d<=in12;}return false;});if(urgent.length)showPanic(urgent);else hidePanic();}
function showPanic(list){
  const banner=document.getElementById('panicBanner');if(banner)banner.classList.add('on');
  const pp=document.getElementById('panicPill');if(pp)pp.style.display='flex';
  const title=document.getElementById('panicTitle');
  if(title)title.textContent=list.length===1?'Due in the next 12 hours':`Due in the next 12 hours (${list.length})`;
  const pl=document.getElementById('panicList');if(pl)pl.textContent=list.map(t=>t.name).join(' · ');
}
function hidePanic(){const b=document.getElementById('panicBanner');if(b)b.classList.remove('on');const pp=document.getElementById('panicPill');if(pp)pp.style.display='none';}

