/** When user_roles.role is counselor, ensure public.counselors has this auth user:
 *  (1) row by user_id, (2) claim active orphan row with same email, (3) insert new row.
 *  Requires Supabase policies counselors_insert_own + counselors_claim_email (see migration). */
/** Platform owner is not a bookable school counselor (Owner control / admin only). */
function fluxIsBookableCounselorEmail(email){
  const e=String(email||'').trim().toLowerCase();
  if(!e)return false;
  try{if(typeof OWNER_EMAIL!=='undefined'&&e===String(OWNER_EMAIL).trim().toLowerCase())return false;}catch(_){}
  return true;
}

/** School counselor email from directory / verification (may differ from auth email). */
async function fluxResolveCounselorSchoolEmail(sb){
  const authEmail=String(currentUser?.email||'').trim().toLowerCase();
  if(!sb||!currentUser)return authEmail;
  try{
    const {data:dir}=await sb.from('staff_directory')
      .select('school_email')
      .eq('claimed_by',currentUser.id)
      .eq('role','counselor')
      .eq('active',true)
      .limit(1)
      .maybeSingle();
    const se=String(dir?.school_email||'').trim().toLowerCase();
    if(se)return se;
  }catch(_){}
  try{
    const {data:svr}=await sb.from('staff_verification_requests')
      .select('school_email')
      .eq('user_id',currentUser.id)
      .limit(1)
      .maybeSingle();
    const se=String(svr?.school_email||'').trim().toLowerCase();
    if(se)return se;
  }catch(_){}
  return authEmail;
}

async function fluxClaimCounselorOrphanByEmail(sb,email){
  const em=String(email||'').trim();
  if(!em||!sb||!currentUser)return null;
  try{
    const {data:orphList}=await sb.from('counselors')
      .select('*')
      .is('user_id',null)
      .ilike('email',em)
      .eq('active',true)
      .order('id',{ascending:true})
      .limit(1);
    const orphan=orphList&&orphList[0];
    if(!orphan?.id)return null;
    const {data:claimed,error}=await sb.from('counselors')
      .update({user_id:currentUser.id})
      .eq('id',orphan.id)
      .is('user_id',null)
      .select()
      .maybeSingle();
    if(!error&&claimed)return claimed;
    if(error)window.__fluxCounselorProvisionError=error;
  }catch(e){window.__fluxCounselorProvisionError=e;}
  return null;
}

/** User-facing explanation when counselor row cannot be linked. */
function fluxCounselorProvisionMessage(sb){
  const authEmail=String(currentUser?.email||'').trim();
  const imp=window.FluxImpersonate?.active?.();
  if(imp&&imp.role==='counselor'){
    return `No counselor profile found for <strong>${esc(imp.email||'that account')}</strong> in the school directory. Seed <code>counselors</code> in Supabase or sign in as the real counselor (not owner preview only).`;
  }
  try{
    if(typeof isOwner==='function'&&isOwner()&&!fluxIsBookableCounselorEmail(authEmail)){
      return 'This login is the <strong>platform owner</strong> account — it is not a school counselor profile. Open <strong>Owner control</strong> to impersonate a counselor, or use an admin/work account instead.';
    }
  }catch(_){}
  if(!fluxIsBookableCounselorEmail(authEmail)){
    return 'This email cannot be used as a bookable counselor. Use your <strong>@bloomfield.org</strong> school account (or ask your admin to link you in Supabase).';
  }
  const err=window.__fluxCounselorProvisionError;
  const code=err?.code||err?.message||'';
  if(String(code).includes('42501')||String(code).toLowerCase().includes('policy')){
    return 'Database policies blocked linking your counselor profile. Apply migration <code>20260518120000_counselor_self_provision.sql</code> and <code>20260534100000_ensure_counselor_profile_rpc.sql</code>, then sign out and back in.';
  }
  return `Flux could not link your account to a counselor profile. Sign in with the same email as the school directory (e.g. <strong>you@bloomfield.org</strong>), not only a personal Gmail. If you already use your school email, apply the latest Supabase migrations and sign out/in, or ask your admin to set <code>counselors.user_id</code> to your user id.`;
}
window.fluxCounselorProvisionMessage=fluxCounselorProvisionMessage;

/** Sync counselors.availability JSON into counselor_availability_slots (lowercase day keys). */
async function fluxUpsertCounselorAvailabilitySlots(sb,counselorId,availability){
  if(!sb||!counselorId||!availability||typeof availability!=='object')return;
  const slots=[];
  const allowed=new Set(['monday','tuesday','wednesday','thursday','friday']);
  for(const [rawDay,times] of Object.entries(availability)){
    const day=String(rawDay||'').trim().toLowerCase();
    if(!allowed.has(day))continue;
    const list=Array.isArray(times)?times:[];
    for(const time_slot of list){
      if(!time_slot)continue;
      slots.push({
        counselor_id:counselorId,
        day_of_week:day,
        time_slot:String(time_slot),
        is_available:true,
        updated_at:new Date().toISOString(),
      });
    }
  }
  if(!slots.length)return;
  try{
    await sb.from('counselor_availability_slots').upsert(slots,{onConflict:'counselor_id,day_of_week,time_slot'});
  }catch(e){console.warn('[Flux] fluxUpsertCounselorAvailabilitySlots',e);}
}
window.fluxUpsertCounselorAvailabilitySlots=fluxUpsertCounselorAvailabilitySlots;

async function ensureCounselorRecord(sb,roleHint){
  if(!sb||!currentUser)return null;
  window.__fluxCounselorProvisionError=null;
  const r=roleHint||(typeof FluxRole!=='undefined'&&FluxRole.current)||window._userRole||'student';
  if(r!=='counselor')return null;

  const imp=window.FluxImpersonate?.active?.();
  if(imp&&imp.role==='counselor'&&imp.email){
    try{
      const {data:impRow}=await sb.from('counselors')
        .select('*')
        .ilike('email',String(imp.email).trim())
        .eq('active',true)
        .order('id',{ascending:true})
        .limit(1)
        .maybeSingle();
      if(impRow){window._counselorRecord=impRow;return impRow;}
    }catch(_){}
  }

  if(!fluxIsBookableCounselorEmail(currentUser.email))return null;
  try{
    if(typeof isOwner==='function'&&isOwner()&&!imp)return null;
  }catch(_){}

  let row=window._counselorRecord;
  if(row&&row.user_id===currentUser.id&&row.active!==false)return row;

  try{
    const {data:rpcRow,error:rpcErr}=await sb.rpc('ensure_counselor_profile');
    if(!rpcErr&&rpcRow){
      window._counselorRecord=rpcRow;
      await deactivateExtraCounselorRows(sb,rpcRow.id);
      if(rpcRow.availability)await fluxUpsertCounselorAvailabilitySlots(sb,rpcRow.id,rpcRow.availability);
      return rpcRow;
    }
    if(rpcErr&&rpcErr.code!=='PGRST202')window.__fluxCounselorProvisionError=rpcErr;
  }catch(e){
    if(!String(e?.message||'').includes('PGRST202'))window.__fluxCounselorProvisionError=e;
  }

  try{
    const {data}=await sb.from('counselors').select('*').eq('user_id',currentUser.id).eq('active',true).order('id',{ascending:true}).limit(1).maybeSingle();
    if(data){window._counselorRecord=data;await deactivateExtraCounselorRows(sb,data.id);return data;}
  }catch(_){}

  try{
    const {data:inactive}=await sb.from('counselors').select('*').eq('user_id',currentUser.id).eq('active',false).order('id',{ascending:true}).limit(1).maybeSingle();
    if(inactive?.id){
      const {data:reactivated,error:reactErr}=await sb.from('counselors')
        .update({active:true,booking_enabled:true})
        .eq('id',inactive.id)
        .select()
        .maybeSingle();
      if(!reactErr&&reactivated){
        window._counselorRecord=reactivated;
        await deactivateExtraCounselorRows(sb,reactivated.id);
        if(reactivated.availability)await fluxUpsertCounselorAvailabilitySlots(sb,reactivated.id,reactivated.availability);
        return reactivated;
      }
      if(reactErr)window.__fluxCounselorProvisionError=reactErr;
    }
  }catch(_){}

  const authEmail=(currentUser.email||'').trim();
  const schoolEmail=await fluxResolveCounselorSchoolEmail(sb);
  const emailsToTry=[...new Set([schoolEmail,authEmail].filter(Boolean).map(e=>String(e).trim().toLowerCase()))];
  for(const em of emailsToTry){
    const claimed=await fluxClaimCounselorOrphanByEmail(sb,em);
    if(claimed){
      window._counselorRecord=claimed;
      await deactivateExtraCounselorRows(sb,claimed.id);
      if(claimed.availability)await fluxUpsertCounselorAvailabilitySlots(sb,claimed.id,claimed.availability);
      return claimed;
    }
  }

  const email=schoolEmail||authEmail;
  try{
    let disp=null;
    try{
      const {data:ur}=await sb.from('user_roles').select('display_name').eq('user_id',currentUser.id).maybeSingle();
      disp=ur?.display_name||null;
    }catch(_){}
    const meta=currentUser.user_metadata||{};
    const display=String(disp||meta.full_name||meta.name||(email?email.split('@')[0]:'')||'Counselor').trim()||'Counselor';
    const letter=display.replace(/[^A-Za-z0-9]/g,'').charAt(0).toUpperCase()||'C';
    const avail={
      monday:['9:00 AM','2:00 PM'],tuesday:['9:00 AM','2:00 PM'],wednesday:['9:00 AM','2:00 PM'],
      thursday:['9:00 AM','2:00 PM'],friday:['9:00 AM','2:00 PM'],
    };
    const {data:ins,error}=await sb.from('counselors').insert({
      user_id:currentUser.id,
      name:display.slice(0,120),
      email:email||null,
      avatar_initial:letter,
      availability:avail,
      booking_enabled:true,
      active:true,
    }).select().maybeSingle();
    if(!error&&ins){
      window._counselorRecord=ins;
      await deactivateExtraCounselorRows(sb,ins.id);
      if(ins.availability)await fluxUpsertCounselorAvailabilitySlots(sb,ins.id,ins.availability);
      return ins;
    }
    if(error&&(error.code==='23505'||String(error.message||'').toLowerCase().includes('unique'))){
      const {data:again}=await sb.from('counselors').select('*').eq('user_id',currentUser.id).maybeSingle();
      if(again){window._counselorRecord=again;await deactivateExtraCounselorRows(sb,again.id);return again;}
    }
    if(error){
      window.__fluxCounselorProvisionError=error;
      console.warn('[Flux] ensureCounselorRecord insert',error);
      if(error.code==='23505'||String(error.message||'').toLowerCase().includes('unique')){
        for(const em of emailsToTry){
          const claimed=await fluxClaimCounselorOrphanByEmail(sb,em);
          if(claimed){
            window._counselorRecord=claimed;
            await deactivateExtraCounselorRows(sb,claimed.id);
            return claimed;
          }
        }
      }
    }
  }catch(e){
    window.__fluxCounselorProvisionError=e;
    console.warn('[Flux] ensureCounselorRecord',e);
  }
  return null;
}

/** One auth user must map to one active counselors row (demo seed + auto-insert dupes). */
async function deactivateExtraCounselorRows(sb,keepId){
  if(!sb||!currentUser||!keepId)return;
  try{
    const {data:dupes}=await sb.from('counselors').select('id').eq('user_id',currentUser.id).eq('active',true);
    const off=(dupes||[]).map(d=>d.id).filter(id=>id&&id!==keepId);
    if(!off.length)return;
    await sb.from('counselors').update({active:false,booking_enabled:false}).in('id',off);
  }catch(_){}
}
window.ensureCounselorRecord=ensureCounselorRecord;

// ── Counselor dashboard ───────────────────────────────────────────
async function renderCounselorDashboard(){
  const host=document.getElementById('counselorDashboardBody');
  if(!host||!currentUser)return;
  try{
    if(typeof FluxRole!=='undefined'&&FluxRole.isWorkMode&&FluxRole.isWorkMode()&&!FluxRole.isCounselor()){
      host.innerHTML='<div style="padding:24px;text-align:center;color:var(--muted2);font-size:.9rem">Counselor tools are only available on <strong>counselor</strong> accounts.</div>';
      return;
    }
  }catch(_){}
  const sb=getSB();if(!sb)return;
  host.innerHTML=`<div class="flux-role-skeleton" aria-busy="true" style="padding:20px">
    <div class="flux-skeleton-pulse flux-role-skel-title" style="height:28px;width:min(280px,70%);margin-bottom:14px"></div>
    <div class="flux-role-skel-grid" style="margin-bottom:14px">
      <div class="flux-skeleton-pulse flux-role-skel-card" style="height:72px"></div>
      <div class="flux-skeleton-pulse flux-role-skel-card" style="height:72px"></div>
      <div class="flux-skeleton-pulse flux-role-skel-card" style="height:72px"></div>
    </div>
    <div class="flux-skeleton-pulse flux-role-skel-strip" style="height:200px"></div>
  </div>`;

  const counselorRow=await ensureCounselorRecord(sb,'counselor');
  if(!counselorRow){
    if(!window.__fluxWarnedCounselorEnsure){
      window.__fluxWarnedCounselorEnsure=1;
      console.warn('[Flux] Counselor profile still missing after auto-provision. Apply migrations 20260518120000 + 20260534100000 (or PASTE-INTO-SUPABASE.sql).',window.__fluxCounselorProvisionError);
    }
    const hint=typeof fluxCounselorProvisionMessage==='function'?fluxCounselorProvisionMessage(sb):'Flux could not link your counselor profile.';
    host.innerHTML=`
      <div class="empty">
        <div class="empty-icon">⚠</div>
        <div class="empty-title">Counselor record not found</div>
        <div class="empty-sub">${hint}</div>
        <button type="button" class="btn-sec" style="margin-top:14px" id="fluxCounselorRetryLink">Try again</button>
      </div>`;
    document.getElementById('fluxCounselorRetryLink')?.addEventListener('click',()=>{
      window._counselorRecord=null;
      window.__fluxWarnedCounselorEnsure=0;
      renderCounselorDashboard();
    });
    return;
  }

  // counselor_appointments.date is a DATE (calendar day), so bound it by the
  // local day — a UTC slice reads as tomorrow after ~7pm in the Americas and
  // hides the rest of today's appointments.
  const today=fluxLocalYMD(new Date());
  let appointments=[];let pendingAppts=[];let messages=[];
  let studentNames={};
  try{
    const [{data:appts},{data:pending}]=await Promise.all([
      sb.from('counselor_appointments')
        .select('*')
        .eq('counselor_id',counselorRow.id)
        .gte('date',today)
        .neq('status','cancelled')
        .order('date',{ascending:true})
        .order('time_slot',{ascending:true})
        .limit(50),
      sb.from('counselor_appointments')
        .select('*')
        .eq('counselor_id',counselorRow.id)
        .eq('status','pending')
        .order('date',{ascending:true})
        .order('time_slot',{ascending:true})
        .limit(40),
    ]);
    appointments=appts||[];
    pendingAppts=pending||[];
    const ids=[...new Set([...appointments,...pendingAppts].map(a=>a.student_id).filter(Boolean))];
    if(window.FluxCounselorAppointments?.loadStudentNames){
      studentNames=await FluxCounselorAppointments.loadStudentNames(sb,ids);
    }else if(ids.length){
      const {data:roles}=await sb.from('user_roles').select('user_id,display_name').in('user_id',ids);
      (roles||[]).forEach(r=>{studentNames[r.user_id]=r.display_name||'Student';});
    }
    const {data:msgs}=await sb.from('flux_messages')
      .select('id,content,sender_id,thread_id,created_at')
      .eq('recipient_id',currentUser.id)
      .eq('read',false)
      .order('created_at',{ascending:false})
      .limit(15);
    messages=msgs||[];
  }catch(e){console.warn('[Flux counselor] load failed',e);}

  const scheduleAppts=appointments.filter(a=>a.status!=='pending');
  const todayAppts=scheduleAppts.filter(a=>a.date===today);
  const upcomingAppts=scheduleAppts.filter(a=>a.date>today);
  const apptLabel=(id)=>esc(studentNames[id]||'Student');
  const pendingRowsHtml=pendingAppts.length?pendingAppts.map(a=>{
    const msg=a.student_requested_message||a.notes||'';
    const dl=new Date(a.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});
    return `<div class="appointment-row appointment-row--pending" data-appt-id="${esc(a.id)}">
      <div class="appt-time">${esc(dl)} · ${esc(a.time_slot)}</div>
      <div class="appt-student">${apptLabel(a.student_id)}</div>
      <div class="appt-reason">${esc((a.reason||'').slice(0,80)||'No reason given')}</div>
      ${msg?`<div class="appt-notes">${esc(msg.slice(0,120))}</div>`:''}
      <div class="appt-status-badge status-pending">pending</div>
      <div class="appt-actions">
        <button type="button" class="appt-btn appt-btn-confirm" data-appt-confirm="${esc(a.id)}">Confirm</button>
        <button type="button" class="appt-btn appt-btn-decline" data-appt-decline="${esc(a.id)}">Decline</button>
      </div>
    </div>`;
  }).join(''):'<div style="font-size:.82rem;color:var(--muted2);padding:8px 0">No pending requests</div>';

  let greetFull='';
  try{
    const imp=window.FluxImpersonate&&FluxImpersonate.active&&FluxImpersonate.active();
    if(imp&&String(imp.name||'').trim())greetFull=String(imp.name).trim();
  }catch(_){}
  if(!greetFull){
    greetFull=String(
      (typeof FluxRole!=='undefined'&&FluxRole.profile&&FluxRole.profile.display_name)
        ||currentUser.user_metadata?.full_name
        ||counselorRow.name
        ||currentUser.email?.split('@')[0]
        ||'Counselor',
    ).trim();
  }
  const greetFirst=greetFull.split(/\s+/).filter(Boolean).filter(w=>!['Mr.','Mrs.','Ms.','Dr.'].includes(w))[0]||greetFull;
  const subjLine=(typeof FluxRole!=='undefined'&&FluxRole.profile&&FluxRole.profile.subject)
    ?String(FluxRole.profile.subject).trim():'';

  let _counselorCaseload=null;
  let _counselorQueue=null;
  try{
    if(window.FluxCounselorCaseload?.enabled?.()&&typeof FluxCounselorCaseload.renderCaseloadDashboard==='function'){
      await FluxCounselorCaseload.renderCaseloadDashboard();
    }
    if(window.FluxCounselorCaseload?.enabled?.()&&typeof FluxCounselorCaseload.loadCaseload==='function'){
      _counselorCaseload=await FluxCounselorCaseload.loadCaseload(sb,counselorRow.id);
    }
    if(window.FluxCounselorRiskQueue?.enabled?.()&&_counselorCaseload&&typeof FluxCounselorRiskQueue.loadQueue==='function'){
      _counselorQueue=await FluxCounselorRiskQueue.loadQueue(sb,counselorRow.id,_counselorCaseload);
      const rqMount=document.getElementById('counselorRiskQueueMount');
      if(rqMount&&typeof FluxCounselorRiskQueue.renderSection==='function'){
        const rqHtml=FluxCounselorRiskQueue.renderSection(_counselorQueue);
        rqMount.innerHTML=rqHtml||'';
        rqMount.hidden=!rqHtml;
      }
    }
    if(window.FluxCounselorCopilot?.setDashboardContext){
      FluxCounselorCopilot.setDashboardContext({
        counselorDbId:counselorRow.id,
        caseload:_counselorCaseload,
        queue:_counselorQueue,
        todayApptCount:todayAppts.length,
        upcomingApptCount:upcomingAppts.length,
        unreadMessages:messages.length,
      });
    }
  }catch(_){}

  host.innerHTML=`
    <div class="counselor-dashboard">
      <div class="teacher-header">
        <div>
          <div class="teacher-greeting">${esc(getTimeGreeting())}, ${esc(greetFirst)}</div>
          <div class="teacher-date">${subjLine?esc(subjLine)+' · ':''}${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</div>
        </div>
        <button type="button" class="teacher-action-btn" onclick="openCounselorAvailabilityEditor('${esc(counselorRow.id)}')">Edit availability</button>
        ${window.FluxCounselorCopilot?.dashboardButtonHtml?.()||''}
      </div>

      <div class="teacher-stats">
        <div class="teacher-stat-card ${pendingAppts.length?'sw-stat-warn':''}">
          <div class="stat-number">${pendingAppts.length}</div>
          <div class="stat-label">Pending requests</div>
        </div>
        <div class="teacher-stat-card">
          <div class="stat-number">${todayAppts.length}</div>
          <div class="stat-label">Today's appointments</div>
        </div>
        <div class="teacher-stat-card">
          <div class="stat-number">${upcomingAppts.length}</div>
          <div class="stat-label">Upcoming</div>
        </div>
        <div class="teacher-stat-card">
          <div class="stat-number">${messages.length}</div>
          <div class="stat-label">Unread messages</div>
        </div>
      </div>

      ${window.FluxCounselorConsent?.enabled?.()&&_counselorCaseload&&window.FluxCounselorConsent.renderCounselorSummary
        ?FluxCounselorConsent.renderCounselorSummary(_counselorCaseload)
        :''}

      <div class="teacher-grid">
        <div class="teacher-section teacher-section--pending">
          <div class="section-header"><h3>Booking requests</h3>${pendingAppts.length?`<span class="sw-mini-tag">${pendingAppts.length} pending</span>`:''}</div>
          ${pendingRowsHtml}
        </div>
        <div class="teacher-section">
          <div class="section-header"><h3>Today's schedule</h3></div>
          ${todayAppts.length?todayAppts.map(a=>`
            <div class="appointment-row">
              <div class="appt-time">${esc(a.time_slot)}</div>
              <div class="appt-student">${apptLabel(a.student_id)}</div>
              <div class="appt-reason">${esc((a.reason||'').slice(0,40)||'No reason given')}</div>
              <div class="appt-status-badge status-${esc(a.status)}">${esc(a.status)}</div>
            </div>`).join('')
            :'<div style="font-size:.82rem;color:var(--muted2);padding:12px 0">No appointments today</div>'}
          ${upcomingAppts.length?`
            <div class="section-header" style="margin-top:20px"><h3>Upcoming (${upcomingAppts.length})</h3></div>
            ${upcomingAppts.slice(0,8).map(a=>`
              <div class="appointment-row">
                <div class="appt-time">${new Date(a.date+'T00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})} ${esc(a.time_slot)}</div>
                <div class="appt-student">${apptLabel(a.student_id)}</div>
                <div class="appt-status-badge status-${esc(a.status)}">${esc(a.status)}</div>
              </div>`).join('')}
          `:''}
        </div>
        <div class="teacher-section">
          <div class="section-header"><h3>Messages${messages.length?` (${messages.length})`:''}</h3></div>
          ${messages.length?messages.slice(0,8).map(m=>`
            <div class="message-preview-row" data-message-sender="${esc(m.sender_id)}">
              <div class="msg-avatar">S</div>
              <div class="msg-info">
                <div class="msg-sender">Student ${esc(String(m.sender_id).slice(0,6))}</div>
                <div class="msg-preview">${esc((m.content||'').slice(0,55))}</div>
              </div>
              <div class="msg-unread-dot" aria-hidden="true"></div>
            </div>`).join('')
            :'<div style="font-size:.82rem;color:var(--muted2);padding:12px 0">No unread messages</div>'}
        </div>
      </div>
    </div>`;

  host.querySelectorAll('[data-message-sender]').forEach(row=>{
    row.addEventListener('click',()=>FluxMessaging.openThreadById(row.dataset.messageSender));
  });
  try{
    const caseloadMount=document.getElementById('counselorCaseloadMount');
    if(window.FluxCounselorCaseload?.wireCounselorSection&&caseloadMount){
      FluxCounselorCaseload.wireCounselorSection(caseloadMount,sb);
    }
  }catch(_){}
  try{
    const rqMount=document.getElementById('counselorRiskQueueMount');
    if(window.FluxCounselorRiskQueue?.wire&&rqMount)FluxCounselorRiskQueue.wire(rqMount,sb);
  }catch(_){}
  try{
    // C11 help-ticket triage (urgent first). Own try block: a ticket-fetch
    // failure must not take the rest of the dashboard down with it.
    if(window.FluxHelpTickets?.injectCounselorTriage)
      await FluxHelpTickets.injectCounselorTriage(sb,counselorRow.id);
  }catch(_){}
  host.querySelectorAll('[data-action="counselor-copilot"]').forEach(b=>b.addEventListener('click',()=>{
    if(window.FluxCounselorCopilot?.open)FluxCounselorCopilot.open();
  }));
  if(window.FluxCounselorAppointments?.wireAppointmentActions){
    FluxCounselorAppointments.wireAppointmentActions(host,counselorRow.id);
  }
  try{if(window.FluxGoogle?.refreshStaffHubMounts)FluxGoogle.refreshStaffHubMounts();}catch(_){}
  try{
    if(window.FluxStaffPlatform?.mountStaffWorkspacePins){
      FluxStaffPlatform.mountStaffWorkspacePins(host.querySelector('.counselor-dashboard')||host,{placement:'after-stats'});
    }
  }catch(_){}
}
window.renderCounselorDashboard=renderCounselorDashboard;

// ── Student "My Counselor" section (rendered into profile panel) ──
async function fetchAssignedStudentCounselor(sb,studentId){
  if(!sb||!studentId)return {link:null,counselor:null,error:null};
  const {data:sc,error:scErr}=await sb.from('student_counselors')
    .select('counselor_id,insights_consent,consent_tier,consented_at')
    .eq('student_id',studentId)
    .maybeSingle();
  if(scErr)return {link:null,counselor:null,error:scErr};
  if(!sc?.counselor_id)return {link:sc||null,counselor:null,error:null};
  const {data:counselor,error:cErr}=await sb.from('counselors')
    .select('*')
    .eq('id',sc.counselor_id)
    .maybeSingle();
  return {link:sc,counselor:counselor||null,error:cErr||null};
}

async function assignStudentCounselor(counselorId){
  const sb=getSB();
  if(!sb||!currentUser?.id||!counselorId){
    return {ok:false,error:'Sign in to select a counselor.'};
  }
  const {error}=await sb.from('student_counselors').upsert(
    {student_id:currentUser.id,counselor_id:counselorId},
    {onConflict:'student_id'},
  );
  if(error)return {ok:false,error:error.message||String(error)};
  try{save('flux_my_counselor_id',counselorId);}catch(_){}
  return {ok:true};
}
window.assignStudentCounselor=assignStudentCounselor;

async function renderMyCounselorSection(){
  const host=document.getElementById('myCounselorSection');
  if(!host||!currentUser)return;
  const sb=getSB();if(!sb)return;

  const pendingStaffMeta=String(currentUser.user_metadata?.role_pending||'').toLowerCase()==='staff';
  if((typeof FluxRole!=='undefined'&&FluxRole.current!=='student')||pendingStaffMeta){
    host.innerHTML='';
    return;
  }

  let counselor=null;
  let scLink=null;
  try{
    const fetched=await fetchAssignedStudentCounselor(sb,currentUser.id);
    scLink=fetched.link;
    counselor=fetched.counselor;
  }catch(_){}

  if(!counselor){
    host.innerHTML=`
      <div class="card">
        <h3>School counselor</h3>
        <div class="empty">
          <div class="empty-icon"></div>
          <div class="empty-title">No counselor selected</div>
          <div class="empty-sub">Pick your counselor to book appointments and send messages.</div>
        </div>
        <button id="pickCounselorBtn" style="width:100%;margin-top:12px">Select counselor</button>
      </div>`;
    host.querySelector('#pickCounselorBtn')?.addEventListener('click',openCounselorSelectModal);
    return;
  }

  // DATE column — bound by local day (see counselor dashboard above).
  const today=fluxLocalYMD(new Date());
  let upcoming=[];
  try{
    const {data}=await sb.from('counselor_appointments')
      .select('id,date,time_slot,reason,status')
      .eq('student_id',currentUser.id)
      .eq('counselor_id',counselor.id)
      .gte('date',today)
      .neq('status','cancelled')
      .order('date',{ascending:true})
      .order('time_slot',{ascending:true})
      .limit(5);
    upcoming=data||[];
  }catch(_){}

  host.innerHTML=`
    <div class="card">
      <h3>My counselor</h3>
      <div class="counselor-profile-row">
        <div class="counselor-avatar-lg" style="background:${esc(counselor.avatar_color||'#7c5cff')}">${esc(counselor.avatar_initial||(counselor.name||'?')[0])}</div>
        <div>
          <div class="counselor-name">${esc(counselor.name)}</div>
          <div class="counselor-bio">${esc((counselor.bio||'').slice(0,120))}</div>
        </div>
      </div>
      <div style="display:flex;gap:8px;margin:14px 0">
        <button id="bookApptBtn" type="button" style="flex:1;padding:10px;font-size:.82rem">Book appointment</button>
        <button id="msgCounselorBtn" type="button" style="flex:1;padding:10px;font-size:.82rem">Message</button>
      </div>
      ${upcoming.length?`
        <div style="font-size:.7rem;text-transform:uppercase;letter-spacing:1px;color:var(--muted);margin-bottom:8px;font-family:'JetBrains Mono',monospace">Upcoming appointments</div>
        ${upcoming.map(a=>`
          <div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:var(--card2);border:1px solid var(--border);border-radius:10px;margin-bottom:6px">
            <div style="font-size:.82rem;font-weight:600;font-family:'JetBrains Mono',monospace;color:var(--accent)">
              ${new Date(a.date+'T00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})} ${esc(a.time_slot)}
            </div>
            <div style="flex:1;font-size:.78rem;color:var(--muted2)">${esc((a.reason||'').slice(0,40)||'No reason')}</div>
            <div class="appt-status-badge status-${esc(a.status)}">${esc(a.status)}</div>
            ${a.status==='pending'?`<button type="button" class="btn-sec" style="padding:4px 8px;font-size:.68rem;flex-shrink:0" data-cancel-appt="${esc(a.id)}">Cancel</button>`:''}
          </div>`).join('')}
      `:'<div style="font-size:.78rem;color:var(--muted2)">No upcoming appointments</div>'}
      ${window.FluxCounselorConsent?.enabled?.()&&window.FluxCounselorConsent.renderStudentPanel
        ?FluxCounselorConsent.renderStudentPanel(String(scLink?.consent_tier||'none'),counselor.name,scLink?.consented_at)
        :window.FluxCounselorCaseload?.consentCheckboxHtml?.(
        !!(scLink&&scLink.insights_consent&&['basic','wellness'].includes(String(scLink.consent_tier||'none'))),
        !!(scLink&&scLink.insights_consent&&String(scLink.consent_tier||'')==='wellness'),
        counselor.name,
        scLink?.consented_at
      )||''}
    </div>`;
  host.querySelector('#bookApptBtn')?.addEventListener('click',()=>{
    if(typeof openBookAppointmentModal==='function')openBookAppointmentModal(counselor.id);
  });
  host.querySelector('#msgCounselorBtn')?.addEventListener('click',()=>{
    if(counselor.user_id&&typeof openMessageComposer==='function')openMessageComposer(counselor.user_id,counselor.name);
    else if(typeof showToast==='function')showToast('This counselor has not linked their account yet.','info');
  });
  host.querySelectorAll('[data-cancel-appt]').forEach(btn=>{
    btn.addEventListener('click',()=>cancelCounselorAppointment(btn.getAttribute('data-cancel-appt')));
  });
  try{
    if(window.FluxCounselorCaseload?.wireStudentConsent&&counselor?.id)
      FluxCounselorCaseload.wireStudentConsent(host,sb,currentUser.id,counselor.id);
  }catch(_){}
  try{
    if(window.FluxCaseloadEngine?.enabled?.()&&window.FluxCaseloadEngine?.renderStudentWellnessCheckin)
      await FluxCaseloadEngine.renderStudentWellnessCheckin(host,counselor);
  }catch(_){}
  try{
    // C11: "Ask for help" + the student's own ticket statuses.
    if(window.FluxHelpTickets?.injectStudentSection)
      await FluxHelpTickets.injectStudentSection(host,counselor);
  }catch(_){}
}
window.renderMyCounselorSection=renderMyCounselorSection;

function openCounselorBookingFromAnywhere(){
  const sb=getSB();
  if(!sb||!currentUser)return;
  sb.from('student_counselors').select('counselor_id').eq('student_id',currentUser.id).maybeSingle()
    .then(({data})=>{
      if(data?.counselor_id){
        if(typeof openBookAppointmentModal==='function')openBookAppointmentModal(data.counselor_id);
      }else if(typeof openCounselorSelectModal==='function')openCounselorSelectModal();
    });
}
window.openCounselorBookingFromAnywhere=openCounselorBookingFromAnywhere;

async function cancelCounselorAppointment(appointmentId){
  const sb=getSB();
  if(!sb||!currentUser||!appointmentId)return;
  try{
    await sb.from('counselor_appointments').update({status:'cancelled'}).eq('id',appointmentId).eq('student_id',currentUser.id);
    if(typeof showToast==='function')showToast('Appointment cancelled','info');
    renderMyCounselorSection();
  }catch(e){
    if(typeof showToast==='function')showToast(String(e.message||e),'error');
  }
}
window.cancelCounselorAppointment=cancelCounselorAppointment;

function openCounselorSelectModal(){
  if(document.getElementById('counselorPickModal'))return;
  const sb=getSB();if(!sb)return;
  const modal=buildEduModal('counselorPickModal',`
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px">
      <h3 style="font-size:1rem;font-weight:800">Pick your counselor</h3>
      <button type="button" class="edu-modal-close" aria-label="Close">✕</button>
    </div>
    <div id="counselorPickError" class="edu-modal-error" style="display:none" role="alert"></div>
    <div id="counselorList" class="counselor-select-list">
      <div style="padding:24px;text-align:center;color:var(--muted2)">Loading…</div>
    </div>`);
    sb.from('counselors').select('*').eq('active',true).eq('booking_enabled',true).then(({data,error})=>{
    const list=document.getElementById('counselorList');
    if(!list)return;
    if(error){
      list.innerHTML=`<div class="edu-modal-error" style="display:block">${esc(error.message||'Could not load counselors')}</div>`;
      return;
    }
    const bookable=(data||[]).filter(c=>fluxIsBookableCounselorEmail(c.email));
    if(!bookable.length){list.innerHTML='<div class="empty"><div class="empty-icon"></div><div class="empty-title">No counselors available</div></div>';return;}
    list.innerHTML=bookable.map(c=>`
      <button type="button" class="counselor-select-card" data-counselor-id="${esc(c.id)}">
        <div class="counselor-avatar" style="background:${esc(c.avatar_color||'#7c5cff')}">${esc(c.avatar_initial||(c.name||'?')[0])}</div>
        <div class="counselor-info">
          <div class="counselor-name">${esc(c.name)}</div>
          <div class="counselor-bio">${esc((c.bio||'').slice(0,140))}</div>
        </div>
        <div class="counselor-select-check">○</div>
      </button>`).join('');
    list.querySelectorAll('[data-counselor-id]').forEach(card=>{
      card.addEventListener('click',async()=>{
        const id=card.getAttribute('data-counselor-id');
        if(!id)return;
        const errEl=modal.querySelector('#counselorPickError');
        list.querySelectorAll('.counselor-select-card').forEach(c=>{
          c.disabled=true;
          c.style.opacity=c===card?'1':'.45';
        });
        if(errEl){errEl.style.display='none';errEl.textContent='';}
        card.querySelector('.counselor-select-check').textContent='…';
        const result=await assignStudentCounselor(id);
        if(!result.ok){
          list.querySelectorAll('.counselor-select-card').forEach(c=>{
            c.disabled=false;
            c.style.opacity='';
            const chk=c.querySelector('.counselor-select-check');
            if(chk)chk.textContent='○';
          });
          const msg=result.error||'Could not save counselor';
          if(errEl){errEl.textContent=msg;errEl.style.display='block';}
          else if(typeof showToast==='function')showToast(msg,'error');
          return;
        }
        document.getElementById('counselorPickModal')?.remove();
        if(typeof showToast==='function')showToast('Counselor saved','success');
        try{await renderMyCounselorSection();}catch(_){}
      });
    });
  });
}
window.openCounselorSelectModal=openCounselorSelectModal;

// ── Appointment booking ───────────────────────────────────────────
let _selectedApptDate=null,_selectedApptTime=null;

function openBookAppointmentModal(counselorId){
  if(document.getElementById('bookApptModal'))return;
  const sb=getSB();if(!sb)return;
  _selectedApptDate=null;_selectedApptTime=null;
  const days=[];
  for(let i=1;i<=14;i++){
    const d=new Date();d.setDate(d.getDate()+i);
    const dow=d.getDay();
    if(dow===0||dow===6)continue;
    days.push({
      date:fluxLocalYMD(d),
      label:d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}),
      dayName:d.toLocaleDateString('en-US',{weekday:'long'}).toLowerCase(),
    });
  }
  const modal=buildEduModal('bookApptModal',`
    <div id="bookApptHeader" style="display:flex;align-items:center;gap:12px;margin-bottom:20px">
      <div id="bookApptAvatar" style="width:40px;height:40px;border-radius:50%;background:#7c5cff;display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;flex-shrink:0">C</div>
      <div>
        <div style="font-size:1rem;font-weight:800" id="bookApptTitle">Book appointment</div>
        <div style="font-size:.75rem;color:var(--muted2)">30-minute meeting</div>
      </div>
      <button type="button" class="edu-modal-close" style="margin-left:auto" aria-label="Close">✕</button>
    </div>
    <div class="mrow"><label>Reason for meeting</label>
      <select id="appt_reason">
        <option>Academic check-in</option>
        <option>Course planning</option>
        <option>College planning</option>
        <option>Personal concern</option>
        <option>Schedule change</option>
        <option>Other</option>
      </select>
    </div>
    <div class="mrow"><label>Additional notes (optional)</label>
      <textarea id="appt_notes" placeholder="Any context you'd like to share…" style="min-height:60px"></textarea>
    </div>
    <div style="font-size:.75rem;font-weight:700;color:var(--muted2);margin-bottom:10px">Select a date</div>
    <div id="dateChips" style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:16px">
      ${days.map(d=>`<button type="button" class="date-chip" data-date="${esc(d.date)}" data-dayname="${esc(d.dayName)}">${esc(d.label)}</button>`).join('')}
    </div>
    <div id="timeSlotContainer" style="display:none">
      <div style="font-size:.75rem;font-weight:700;color:var(--muted2);margin-bottom:10px">Select a time</div>
      <div id="timeSlots" style="display:flex;gap:6px;flex-wrap:wrap"></div>
    </div>
    <div id="apptError" class="edu-modal-error" style="display:none;margin-top:12px"></div>
    <button id="confirmApptBtn" style="display:none;width:100%;margin-top:16px;padding:13px;background:var(--accent);border:none;border-radius:12px;color:#0a0d18;font-weight:700;cursor:pointer">Confirm appointment</button>
  `);
  sb.from('counselors').select('name,avatar_color,avatar_initial,availability').eq('id',counselorId).maybeSingle()
    .then(({data:c})=>{
      if(!c)return;
      document.getElementById('bookApptTitle').textContent=`Book with ${c.name}`;
      const av=document.getElementById('bookApptAvatar');
      if(av){
        av.style.background=c.avatar_color||'#7c5cff';
        av.textContent=c.avatar_initial||(c.name||'?')[0];
      }
    });
  modal.querySelectorAll('[data-date]').forEach(btn=>{
    btn.addEventListener('click',()=>selectAppointmentDate(btn,counselorId));
  });
  modal.querySelector('#confirmApptBtn')?.addEventListener('click',()=>confirmAppointment(counselorId));
}
window.openBookAppointmentModal=openBookAppointmentModal;

async function selectAppointmentDate(btn,counselorId){
  const sb=getSB();if(!sb)return;
  _selectedApptDate=btn.dataset.date;
  _selectedApptTime=null;
  const dayName=btn.dataset.dayname;
  document.querySelectorAll('#dateChips .date-chip').forEach(b=>{
    b.style.background='';b.style.borderColor='';b.style.color='';
  });
  btn.style.background='rgba(var(--accent-rgb),.15)';
  btn.style.borderColor='var(--accent)';
  btn.style.color='var(--accent)';

  let availability=[];
  try{
    const {data:c}=await sb.from('counselors').select('availability').eq('id',counselorId).maybeSingle();
    availability=c?.availability?.[dayName]||[];
    if(!availability.length&&c?.availability){
      const allSlots=Object.values(c.availability).flat();
      if(!allSlots.length){
        availability=['9:00 AM','9:30 AM','10:00 AM','10:30 AM','11:00 AM','11:30 AM','1:00 PM','1:30 PM','2:00 PM','2:30 PM','3:00 PM'];
      }
    }
  }catch(_){
    availability=['9:00 AM','9:30 AM','10:00 AM','10:30 AM','11:00 AM','11:30 AM','1:00 PM','1:30 PM','2:00 PM','2:30 PM','3:00 PM'];
  }
  let booked=new Set();
  try{
    const {data:b}=await sb.from('counselor_appointments')
      .select('time_slot,status')
      .eq('counselor_id',counselorId)
      .eq('date',_selectedApptDate);
    booked=new Set((b||[]).filter(x=>x.status!=='cancelled').map(x=>x.time_slot));
  }catch(_){}

  const container=document.getElementById('timeSlotContainer');
  const slotsEl=document.getElementById('timeSlots');
  if(!container||!slotsEl)return;
  if(!availability.length){
    slotsEl.innerHTML='<div style="font-size:.8rem;color:var(--muted2)">No availability on this day. Try another date.</div>';
  }else{
    slotsEl.innerHTML=availability.map(slot=>{
      const isBooked=booked.has(slot);
      return `<button type="button" class="time-chip ${isBooked?'booked':''}" data-slot="${esc(slot)}" ${isBooked?'disabled':''}>${esc(slot)}${isBooked?' ✓':''}</button>`;
    }).join('');
    slotsEl.querySelectorAll('.time-chip:not(.booked)').forEach(b=>{
      b.addEventListener('click',()=>selectApptTime(b,b.dataset.slot));
    });
  }
  container.style.display='block';
  document.getElementById('confirmApptBtn').style.display='none';
}
window.selectAppointmentDate=selectAppointmentDate;

function selectApptTime(btn,slot){
  _selectedApptTime=slot;
  document.querySelectorAll('.time-chip:not(.booked)').forEach(b=>{
    b.style.background='';b.style.borderColor='';b.style.color='';
  });
  btn.style.background='rgba(var(--accent-rgb),.15)';
  btn.style.borderColor='var(--accent)';
  btn.style.color='var(--accent)';
  const c=document.getElementById('confirmApptBtn');
  if(c)c.style.display='block';
}
window.selectApptTime=selectApptTime;

async function confirmAppointment(counselorId){
  if(!_selectedApptDate||!_selectedApptTime)return;
  const sb=getSB();if(!sb)return;
  const reason=document.getElementById('appt_reason')?.value||'General check-in';
  const notes=document.getElementById('appt_notes')?.value.trim();
  const errEl=document.getElementById('apptError');
  const confirmBtn=document.getElementById('confirmApptBtn');
  const setErr=(t)=>{if(errEl){errEl.textContent=t;errEl.style.display='block';}if(confirmBtn){confirmBtn.disabled=false;confirmBtn.textContent='Confirm appointment';}};
  if(confirmBtn){confirmBtn.disabled=true;confirmBtn.textContent='Booking…';}
  const {error}=await sb.from('counselor_appointments').insert({
    counselor_id:counselorId,
    student_id:currentUser.id,
    date:_selectedApptDate,
    time_slot:_selectedApptTime,
    reason,
    notes:notes||null,
    status:'pending',
    duration_minutes:30,
  });
  if(error){setErr(error.message||'Could not book appointment. Please try again.');return;}
  document.getElementById('bookApptModal')?.remove();
  const rect=confirmBtn?.getBoundingClientRect();
  if(rect&&window.FluxMagic?.particles)FluxMagic.particles(rect.left+rect.width/2,rect.top,{count:10});
  showToast(`Booked for ${new Date(_selectedApptDate+'T00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})} at ${_selectedApptTime}`,'success');
  _selectedApptDate=null;_selectedApptTime=null;
  renderMyCounselorSection();
}
window.confirmAppointment=confirmAppointment;

// ── Realtime messaging ────────────────────────────────────────────
const FluxMessaging={
  _subscription:null,
  _activeThread:null,

  async openThread(otherUserId,otherName){
    if(!otherUserId||otherUserId==='undefined'){
      showToast('That counselor has not yet activated their Flux account','error');
      return;
    }
    const sb=getSB();if(!sb||!currentUser)return;
    const myId=currentUser.id;
    let thread=null;
    try{
      const {data}=await sb.from('flux_threads')
        .select('*')
        .or(`and(participant_1.eq.${myId},participant_2.eq.${otherUserId}),and(participant_1.eq.${otherUserId},participant_2.eq.${myId})`)
        .limit(1)
        .maybeSingle();
      thread=data||null;
    }catch(_){}
    if(!thread){
      try{
        const {data:nt}=await sb.from('flux_threads').insert({
          participant_1:myId,
          participant_2:otherUserId,
          subject:`Message with ${otherName||'user'}`,
        }).select().single();
        thread=nt;
      }catch(e){
        showToast('Could not open message thread','error');
        return;
      }
    }
    if(!thread)return;
    this._activeThread=thread;
    this.renderMessageModal(thread,otherName||'User',otherUserId);
    this.subscribeToThread(thread.id);
  },

  async openThreadById(otherUserId){
    if(!otherUserId)return;
    const sb=getSB();if(!sb)return;
    let displayName='User';
    try{
      const {data}=await sb.from('user_roles').select('display_name').eq('user_id',otherUserId).maybeSingle();
      if(data?.display_name)displayName=data.display_name;
    }catch(_){}
    this.openThread(otherUserId,displayName);
  },

  renderMessageModal(thread,otherName,otherUserId){
    document.getElementById('messageModal')?.remove();
    const modal=document.createElement('div');
    modal.id='messageModal';
    modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.8);z-index:600;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(8px)';
    modal.innerHTML=`
      <div style="background:var(--card);border:1px solid var(--border2);border-radius:20px;width:100%;max-width:500px;height:80vh;display:flex;flex-direction:column;box-shadow:var(--shadow-float,0 12px 40px rgba(0,0,0,.5))">
        <div style="display:flex;align-items:center;gap:12px;padding:16px 18px;border-bottom:1px solid var(--border);flex-shrink:0">
          <div style="width:36px;height:36px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;font-weight:700;color:#0a0d18;flex-shrink:0">${esc((otherName||'?')[0])}</div>
          <div style="flex:1">
            <div style="font-size:.9rem;font-weight:700">${esc(otherName)}</div>
            <div style="font-size:.7rem;color:var(--muted2)">Direct message</div>
          </div>
          <button id="msgModalClose" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:1.1rem;padding:0">✕</button>
        </div>
        <div id="messageList" style="flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:8px"></div>
        <div style="padding:12px 16px;border-top:1px solid var(--border);flex-shrink:0;display:flex;gap:8px">
          <textarea id="messageInput" placeholder="Write a message…" rows="1" style="flex:1;resize:none;background:var(--card2);border:1px solid var(--border2);border-radius:12px;padding:10px 14px;font-family:inherit;font-size:.85rem;color:var(--text);min-height:44px;max-height:100px;overflow-y:auto"></textarea>
          <button id="messageSendBtn" style="padding:10px 14px;background:var(--accent);border:none;border-radius:12px;color:#0a0d18;font-weight:700;cursor:pointer;align-self:flex-end">Send</button>
        </div>
      </div>`;
    document.body.appendChild(modal);
    const closeAll=()=>{modal.remove();this.unsubscribe();};
    modal.addEventListener('click',e=>{if(e.target===modal)closeAll();});
    document.getElementById('msgModalClose')?.addEventListener('click',closeAll);
    document.getElementById('messageSendBtn')?.addEventListener('click',()=>this.sendMessage(otherUserId));
    document.getElementById('messageInput')?.addEventListener('keydown',e=>{
      if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();this.sendMessage(otherUserId);}
    });
    this.loadMessages(thread.id);
  },

  async loadMessages(threadId){
    const sb=getSB();if(!sb)return;
    let messages=[];
    try{
      const {data}=await sb.from('flux_messages')
        .select('*')
        .eq('thread_id',threadId)
        .order('created_at',{ascending:true})
        .limit(50);
      messages=data||[];
    }catch(_){}
    const list=document.getElementById('messageList');
    if(!list)return;
    list.innerHTML=messages.map(m=>this.renderMessage(m)).join('');
    list.scrollTop=list.scrollHeight;
    try{
      await sb.from('flux_messages')
        .update({read:true,read_at:new Date().toISOString()})
        .eq('thread_id',threadId)
        .eq('recipient_id',currentUser.id)
        .eq('read',false);
    }catch(_){}
  },

  renderMessage(msg){
    const isMe=msg.sender_id===currentUser?.id;
    const time=new Date(msg.created_at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
    return `
      <div style="display:flex;flex-direction:column;align-items:${isMe?'flex-end':'flex-start'}">
        <div style="max-width:80%;padding:9px 13px;border-radius:${isMe?'14px 14px 4px 14px':'14px 14px 14px 4px'};background:${isMe?'rgba(var(--accent-rgb),.18)':'var(--card2)'};border:1px solid ${isMe?'rgba(var(--accent-rgb),.25)':'var(--border2)'};font-size:.84rem;line-height:1.5;word-break:break-word">
          ${esc(msg.content)}
        </div>
        <div style="font-size:.65rem;color:var(--muted);margin-top:3px;font-family:'JetBrains Mono',monospace">${time}</div>
      </div>`;
  },

  async sendMessage(recipientId){
    const input=document.getElementById('messageInput');
    const content=input?.value?.trim();
    if(!content||!this._activeThread)return;
    const sb=getSB();if(!sb)return;
    input.value='';
    const {error}=await sb.from('flux_messages').insert({
      thread_id:this._activeThread.id,
      sender_id:currentUser.id,
      recipient_id:recipientId,
      content,
    });
    if(!error){
      sb.from('flux_threads').update({
        last_message_at:new Date().toISOString(),
        last_message_preview:content.slice(0,80),
      }).eq('id',this._activeThread.id);
    }
  },

  subscribeToThread(threadId){
    this.unsubscribe();
    const sb=getSB();if(!sb)return;
    try{
      this._subscription=sb.channel(`thread_${threadId}`)
        .on('postgres_changes',{
          event:'INSERT',schema:'public',table:'flux_messages',
          filter:`thread_id=eq.${threadId}`,
        },payload=>{
          const list=document.getElementById('messageList');
          if(!list)return;
          const wrap=document.createElement('div');
          wrap.innerHTML=this.renderMessage(payload.new);
          if(wrap.firstElementChild)list.appendChild(wrap.firstElementChild);
          list.scrollTop=list.scrollHeight;
        })
        .subscribe();
    }catch(e){console.warn('[Flux msg] subscribe failed',e);}
  },

  unsubscribe(){
    if(!this._subscription)return;
    try{getSB()?.removeChannel(this._subscription);}catch(_){}
    this._subscription=null;
  },
};
window.FluxMessaging=FluxMessaging;

/** Create or reuse a DM thread and insert a message (used for join approvals, etc.). */
async function fluxEnsureThreadAndSend(recipientId, content){
  const sb=getSB();
  if(!sb||!currentUser||!recipientId||!content)return false;
  const myId=currentUser.id;
  if(recipientId===myId)return false;
  let threadId=null;
  try{
    const {data}=await sb.from('flux_threads')
      .select('id')
      .or(`and(participant_1.eq.${myId},participant_2.eq.${recipientId}),and(participant_1.eq.${recipientId},participant_2.eq.${myId})`)
      .limit(1)
      .maybeSingle();
    if(data?.id)threadId=data.id;
  }catch(_){}
  if(!threadId){
    try{
      const {data:nt,error}=await sb.from('flux_threads').insert({
        participant_1:myId,
        participant_2:recipientId,
        subject:'Flux',
      }).select('id').single();
      if(error||!nt?.id)return false;
      threadId=nt.id;
    }catch(_){return false;}
  }
  try{
    const {error}=await sb.from('flux_messages').insert({
      thread_id:threadId,
      sender_id:myId,
      recipient_id:recipientId,
      content:String(content).slice(0,4000),
    });
    if(error)return false;
    await sb.from('flux_threads').update({
      last_message_at:new Date().toISOString(),
      last_message_preview:String(content).slice(0,80),
    }).eq('id',threadId);
  }catch(_){return false;}
  return true;
}
window.fluxEnsureThreadAndSend=fluxEnsureThreadAndSend;

/** School-wide urgent / important banners (requires `school_announcements` migration). */
async function checkForActiveAnnouncements(){
  if(!currentUser)return;
  try{
    if(window.FluxSchoolEmergency?.enabled?.()&&document.body.getAttribute('data-school-broadcast')==='emergency')return;
  }catch(_){}
  const sb=getSB();
  if(!sb)return;
  let rows=[];
  try{
    const iso=new Date().toISOString();
    const {data}=await sb.from('school_announcements')
      .select('id,title,body,priority,created_at')
      .in('priority',['important','urgent','emergency'])
      .or(`expires_at.is.null,expires_at.gt.${iso}`)
      .order('created_at',{ascending:false})
      .limit(5);
    rows=data||[];
  }catch(_){return;}
  const dismissed=typeof load==='function'?load('flux_dismissed_announcements',[]):[];
  const pick=rows.find(r=>r&&r.id&&!dismissed.includes(r.id));
  if(!pick)return;
  document.getElementById('fluxSchoolAnnounceBanner')?.remove();
  const pri=pick.priority||'important';
  const bg=pri==='emergency'?'linear-gradient(135deg,#7f1d1d,#b91c1c)':pri==='urgent'?'rgba(234,88,12,.92)':pri==='important'?'rgba(245,166,35,.9)':'rgba(var(--accent-rgb),.88)';
  const icon=pri==='emergency'?'🚨':pri==='urgent'?'🔴':pri==='important'?'⚠':'📢';
  const bar=document.createElement('div');
  bar.id='fluxSchoolAnnounceBanner';
  bar.style.cssText=`position:fixed;top:52px;left:0;right:0;z-index:400;background:${bg};color:#fff;padding:10px 16px;display:flex;align-items:center;gap:10px;box-shadow:0 4px 24px rgba(0,0,0,.35)`;
  bar.innerHTML=`
    <span style="font-size:1.1rem;flex-shrink:0">${icon}</span>
    <div style="flex:1;min-width:0">
      <strong style="font-size:.85rem;display:block">${esc(pick.title||'Announcement')}</strong>
      <div style="font-size:.78rem;opacity:.92;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(String(pick.body||'').slice(0,140))}${String(pick.body||'').length>140?'…':''}</div>
    </div>
    <button type="button" class="flux-sa-dismiss" style="flex-shrink:0;background:rgba(255,255,255,.2);border:1px solid rgba(255,255,255,.35);border-radius:8px;color:#fff;padding:5px 10px;cursor:pointer;font-size:.78rem;font-weight:700">Dismiss</button>`;
  document.body.appendChild(bar);
  bar.querySelector('.flux-sa-dismiss')?.addEventListener('click',()=>{
    try{
      const d=load('flux_dismissed_announcements',[]);
      if(!d.includes(pick.id)){d.push(pick.id);save('flux_dismissed_announcements',d);}
    }catch(_){}
    bar.remove();
  });
}
window.checkForActiveAnnouncements=checkForActiveAnnouncements;

